// Reading a Form 4: the report an officer, director or 10% owner files within
// two business days of trading the company's stock (phase nine, stage 6).
// Pure, so it is tested on real filings saved as fixtures.
//
// Form 4 is filed as XML in one schema (ownershipDocument), generated by a
// handful of filing agents. Read with patterns rather than a parser library:
// the structure is flat and regular, and every field read here is checked
// against real filings from NVIDIA, Apple, JPMorgan and Culp (November 2026).

export type Form4Owner = { name: string; cik: string | null; role: string | null };

export type Form4Trade = {
  // Position in the filing: non-derivative lines first, then derivative.
  line: number;
  isDerivative: boolean;
  security: string | null;
  date: string | null;
  // The SEC's transaction code: P purchase, S sale, A grant, M option
  // exercise, F tax withholding, G gift, and rarer ones.
  code: string;
  acquiredDisposed: "A" | "D" | null;
  shares: number | null;
  price: number | null;
  sharesAfter: number | null;
  ownership: "D" | "I" | null;
  onPlan: boolean;
};

export type Form4 = { documentType: string; owners: Form4Owner[]; trades: Form4Trade[] };

// One trade as stored and shown: the line from the filing, with the filing's
// own details. Joint filers (a person and their trust, say) share one line.
export type InsiderTrade = Omit<Form4Trade, "line"> & {
  accession: string;
  line: number;
  filedAt: string;
  form: string;
  ownerName: string;
  ownerCik: string | null;
  ownerRole: string | null;
};

export function tradesFromFiling(parsed: Form4, filing: { accession: string; filed: string; form: string }): InsiderTrade[] {
  const first = parsed.owners[0];
  const ownerName = parsed.owners.map((o) => o.name).join(" and ") || "Unnamed";
  return parsed.trades.map((t) => ({
    ...t,
    accession: filing.accession,
    filedAt: filing.filed,
    form: filing.form,
    ownerName,
    ownerCik: first?.cik ?? null,
    ownerRole: first?.role ?? null,
  }));
}

function decode(s: string): string {
  return s
    .replace(/&#x([0-9a-f]+);/gi, (_, h: string) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d: string) => String.fromCodePoint(Number(d)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");
}

function blocks(xml: string, tag: string): string[] {
  return [...xml.matchAll(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`, "g"))].map((m) => m[1]);
}

// A field's text: the element's own text, or its <value> child's.
function field(block: string, tag: string): string | null {
  const m = block.match(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`));
  if (!m) return null;
  const inner = m[1].match(/<value>([\s\S]*?)<\/value>/)?.[1] ?? m[1];
  const text = decode(inner.replace(/<[^>]+>/g, "")).trim();
  return text || null;
}

function numberField(block: string, tag: string): number | null {
  const v = field(block, tag);
  if (v == null) return null;
  const n = Number(v.replace(/,/g, ""));
  return Number.isFinite(n) ? n : null;
}

// "1" and "true" both appear, depending on the filing agent.
function flag(v: string | null): boolean {
  return v === "1" || v?.toLowerCase() === "true";
}

function ownerRole(block: string): string | null {
  const roles: string[] = [];
  if (flag(field(block, "isDirector"))) roles.push("Director");
  if (flag(field(block, "isOfficer"))) roles.push(field(block, "officerTitle") ?? "Officer");
  if (flag(field(block, "isTenPercentOwner"))) roles.push("10% owner");
  if (flag(field(block, "isOther"))) roles.push(field(block, "otherText") ?? "Other");
  return roles.length ? roles.join(", ") : null;
}

// A footnote that says the trade was made under a Rule 10b5-1 plan, and
// doesn't say it wasn't.
function mentionsPlan(text: string): boolean {
  return /10b5-1/i.test(text) && !/\bnot\b[^.]{0,60}10b5-1/i.test(text);
}

export function parseForm4(xml: string): Form4 | null {
  if (!/<ownershipDocument>/.test(xml)) return null;
  const documentType = field(xml, "documentType") ?? "";
  if (!/^4(\/A)?$/.test(documentType)) return null;

  const owners: Form4Owner[] = blocks(xml, "reportingOwner").map((b) => ({
    name: field(b, "rptOwnerName") ?? "Unnamed",
    cik: field(b, "rptOwnerCik"),
    role: ownerRole(b),
  }));

  const footnotes = new Map<string, string>();
  for (const m of xml.matchAll(/<footnote id="([^"]+)">([\s\S]*?)<\/footnote>/g)) footnotes.set(m[1], decode(m[2]));
  const planFootnoted = (b: string) =>
    [...b.matchAll(/<footnoteId id="([^"]+)"\s*\/>/g)].some((m) => mentionsPlan(footnotes.get(m[1]) ?? ""));

  const raw = [
    ...blocks(xml, "nonDerivativeTransaction").map((b) => ({ b, isDerivative: false })),
    ...blocks(xml, "derivativeTransaction").map((b) => ({ b, isDerivative: true })),
  ];

  // The plan: a trade's own footnote, or else the filing's checkbox. The box
  // is one per filing, so it covers the market trades only when none of them
  // is footnoted either way (Apple's filings footnote the sales and not the
  // vesting beside them).
  const anyFootnoted = raw.some(({ b }) => planFootnoted(b));
  const boxTicked = flag(field(xml, "aff10b5One"));

  const trades: Form4Trade[] = raw.map(({ b, isDerivative }, line) => {
    const code = field(b, "transactionCode") ?? "?";
    const ad = field(b, "transactionAcquiredDisposedCode");
    const own = field(b, "directOrIndirectOwnership");
    const marketTrade = code === "P" || code === "S";
    return {
      line,
      isDerivative,
      security: field(b, "securityTitle"),
      date: field(b, "transactionDate")?.slice(0, 10) ?? null,
      code,
      acquiredDisposed: ad === "A" || ad === "D" ? ad : null,
      shares: numberField(b, "transactionShares"),
      price: numberField(b, "transactionPricePerShare"),
      sharesAfter: numberField(b, "sharesOwnedFollowingTransaction"),
      ownership: own === "D" || own === "I" ? own : null,
      onPlan: planFootnoted(b) || (marketTrade && boxTicked && !anyFootnoted),
    };
  });

  return { documentType, owners, trades };
}

// The raw XML's path within the filing. The submissions file names the
// human-readable rendering ("xslF345X06/form4.xml"); the XML itself is the
// same file name without that folder.
export function form4XmlName(primaryDocument: string): string {
  return primaryDocument.replace(/^xslF345X\d+\//i, "");
}
